import{d as o,C as t,o as h,c as m,j as e,a as i,E as a,a3 as u}from"./chunks/framework.Q4yG9rk_.js";const x=JSON.parse('{"title":"论语·为政","description":"《论语》第 2 篇「为政」——二十四章原文与导读。为政以德、十五志学、温故知新、学思并重，以及「知之为知之」。","frontmatter":{"title":"论语·为政","description":"《论语》第 2 篇「为政」——二十四章原文与导读。为政以德、十五志学、温故知新、学思并重，以及「知之为知之」。","category":"guide","aliases":["为政","为政篇","为政第二","论语为政","lunyu 为政"],"source":["《论语》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/lunyu/chapter-02.md","filePath":"lizhimingde/sishu-wujing/lunyu/chapter-02.md","lastUpdated":1790316338000}'),y={name:"lizhimingde/sishu-wujing/lunyu/chapter-02.md"},c=o({...y,setup(d){const s=[{id:"yi",label:"一、为政以德",showLabel:!0,sentences:[["子曰：“为政以",{text:"德",glossary:"de"},"，譬如",{text:"北辰",glossary:"beichen"},"，居其所而众星",{text:"共",glossary:"gong"},"之。”"]],note:"「为政以德，譬如北辰，居其所而众星共之」——以德治国，就像北极星：安居其所，而众星自然环绕（共＝拱）。言德之为政，是「不动而化」。"},{id:"er",label:"二、思无邪",showLabel:!0,sentences:[["子曰：“《诗》三百，一言以",{text:"蔽",glossary:"bi"},"之，曰：",{text:"思无邪",glossary:"siwuxie"},"。”"]],note:"孔子评《诗》：「《诗》三百，一言以蔽之，曰：思无邪」——三百篇用一句话概括，就是「思无邪」（思想纯正）。此章是孔子论《诗》的总纲。"},{id:"san",label:"三、道之以德，齐之以礼",showLabel:!0,sentences:[["子曰：“",{text:"道之以政",glossary:"daozhiyizheng"},"，",{text:"齐之以刑",glossary:"qizhiyixing"},"，民免而无耻。道之以德，齐之以礼，有耻且",{text:"格",glossary:"ge"},"。”"]],note:"「道之以政，齐之以刑，民免而无耻」——用政令引导、用刑罚约束，百姓只求免罪而不知羞耻；「道之以德，齐之以礼，有耻且格」——用德行引导、用礼来齐一，百姓则「有耻且格」（格＝来、归附，一说「正」）。此章是德治与刑罚的分野。"},{id:"si",label:"四、十五志于学",showLabel:!0,sentences:[["子曰：“吾十有",{text:"五",glossary:"shiwu"},"而",{text:"志于学",glossary:"zhiyuxue"},"，三十而立，四十而不惑，五十而知",{text:"天命",glossary:"tianming"},"，六十而",{text:"耳顺",glossary:"ershun"},"，七十而从心所欲，不",{text:"逾矩",glossary:"yuju"},"。”"]],note:"孔子自述一生进境：「吾十有五而志于学，三十而立，四十而不惑，五十而知天命，六十而耳顺，七十而从心所欲，不逾矩」——十五立志向学，三十立定，四十不惑，五十知天命，六十耳顺（于一切言皆通达不逆），七十随心所欲而不越规矩。六个节点，是中国最著名的一段自述。"},{id:"wu",label:"五、生事之以礼",showLabel:!0,sentences:[["孟懿子问孝，子曰：“无违。”樊迟御，子告之曰：“孟孙问孝于我，我对曰‘无违’。”樊迟曰：“何谓也？”子曰：“生，事之以礼；死，葬之以礼，祭之以礼。”"]],note:"孟懿子问孝，孔子答「无违」。樊迟为孔子驾车，孔子告诉他「孟孙问孝于我，我对曰无违」；樊迟再问，孔子遂释：「生，事之以礼；死，葬之以礼，祭之以礼」——「无违」是不违背礼，并非不违父母之意。"},{id:"liu",label:"六、父母唯其疾之忧",showLabel:!0,sentences:[["孟武伯问孝。子曰：“父母唯其",{text:"疾",glossary:"ji"},"之忧。”"]],note:"孟武伯问孝。孔子答：「父母唯其疾之忧」——做父母的，只为子女的疾病担忧（一说：子女只应以父母的疾病为忧）。言孝子当自爱其身，不使父母另有忧虑。"},{id:"qi",label:"七、不敬，何以别乎",showLabel:!0,sentences:[["子游问孝。子曰：“今之孝者，是谓能",{text:"养",glossary:"yang"},"。至于犬马，皆能有养；不",{text:"敬",glossary:"jing"},"，何以别乎？”"]],note:"子游问孝。孔子说：如今所谓的孝，只是能供养（养）。可是犬马也都有人饲养；「不敬，何以别乎」——若无敬，拿什么区别？此章点出「敬」是孝与养的分界。"},{id:"ba",label:"八、色难",showLabel:!0,sentences:[["子夏问孝。子曰：“",{text:"色难",glossary:"senan"},"。有事，弟子服其劳；有酒食，先生",{text:"馔",glossary:"zhuan"},"，曾是以为孝乎？”"]],note:"子夏问孝。孔子说：「色难」——于承事父母，最难的是和悦的颜色。「有事，弟子服其劳；有酒食，先生馔」——有事年轻人代劳，有酒食让长者先吃，难道这就算孝了吗？言孝不在仪节而在诚色。"},{id:"jiu",label:"九、退而省其私",showLabel:!0,sentences:[["子曰：“吾与回言终日，不违，如愚。退而省其私，亦足以发，回也不愚。”"]],note:"孔子说：我整天与颜回讲论，他从不反问，像是愚钝；「退而省其私，亦足以发」——退下去考察他私下的言行，却足以发明我所说的道理。「回也不愚」——颜回并不愚。此章写颜回「默而识之」之学。"},{id:"shi",label:"十、视其所以",showLabel:!0,sentences:[["子曰：“视其所以，观其所由，察其所安。人焉",{text:"廋",glossary:"sou"},"哉？人焉廋哉？”"]],note:"观人之法：「视其所以」（看他所做的事），「观其所由」（看他做事的缘由），「察其所安」（看他安心于什么）。「人焉廋哉？人焉廋哉」——他还能藏到哪里去（廋＝藏）？三句层层深入，是儒家的观人法。"},{id:"shiyi",label:"十一、温故而知新",showLabel:!0,sentences:[["子曰：“",{text:"温故而知新",glossary:"wenguerzhixin"},"，可以为师矣。”"]],note:"「温故而知新，可以为师矣」——温习旧的而能有新得，就可以作老师了。所重在由「故」得「新」，而非止于记诵。"},{id:"shier",label:"十二、君子不器",showLabel:!0,sentences:[["子曰：“君子不",{text:"器",glossary:"qi"},"。”"]],note:"「君子不器」——君子不像器皿（器皿各有专用，不能相通）。言君子当通才达道，不限于一技一用。"},{id:"shisan",label:"十三、先行其言",showLabel:!0,sentences:[["子贡问君子。子曰：“",{text:"先行其言",glossary:"xianxingqiyan"},"而后从之。”"]],note:"子贡问怎样才算君子。孔子答：「先行其言而后从之」——先做了，然后再说。此章针对子贡善言语的特点而发。"},{id:"shisi",label:"十四、周而不比",showLabel:!0,sentences:[["子曰：“君子",{text:"周而不比",glossary:"zhouerbuibi"},"，小人比而不周。”"]],note:"「君子周而不比，小人比而不周」——君子团结而不结党（周＝普遍相亲，比＝朋比为私），小人结党而不团结。周、比之别，在公与私。"},{id:"shiwu",label:"十五、学而不思则罔",showLabel:!0,sentences:[["子曰：“学而不思则",{text:"罔",glossary:"wang"},"，思而不学则",{text:"殆",glossary:"dai"},"。”"]],note:"「学而不思则罔，思而不学则殆」——只学而不思考，便迷惘无所得（罔）；只思而不学，便疑惑不安（殆）。此章言学与思当相济。"},{id:"shiliu",label:"十六、攻乎异端",showLabel:!0,sentences:[["子曰：“",{text:"攻乎异端",glossary:"gonghuyiduan"},"，斯害也已！”"]],note:"「攻乎异端，斯害也已」——专治异端之学（一说「攻击异端」），那就有害了（一说「害就止息了」）。此章异解甚多，关键在「攻」与「异端」二字的取义。"},{id:"shiqi",label:"十七、知之为知之",showLabel:!0,sentences:[["子曰：“由，",{text:"诲女",glossary:"huiru"},"知之乎！知之为知之，不知为不知，是",{text:"知",glossary:"zhizhi"},"也。”"]],note:"孔子对仲由（子路）说：「诲女（汝）知之乎」——我教给你什么叫「知」：「知之为知之，不知为不知，是知也」——知道就是知道，不知道就是不知道，这才是真正的知。"},{id:"shiba",label:"十八、多闻阙疑",showLabel:!0,sentences:[["子张",{text:"学干禄",glossary:"xueganlu"},"。子曰：“多闻",{text:"阙疑",glossary:"queyi"},"，慎言其余，则",{text:"寡尤",glossary:"guayou"},"；多见阙殆，慎行其余，则寡悔。言寡尤，行寡悔，禄在其中矣。”"]],note:"子张问求禄（干禄）。孔子答：「多闻阙疑，慎言其余，则寡尤」——多听，存疑不道，其余谨慎地说，就少过错（尤＝过）；「多见阙殆，慎行其余，则寡悔」——多看，危殆处避开，其余谨慎地做，就少悔恨。「言寡尤，行寡悔，禄在其中矣」——禄位就在其中。"},{id:"shijiu",label:"十九、举直错诸枉",showLabel:!0,sentences:[["哀公问曰：“何为则民服？”孔子对曰：“",{text:"举直错诸枉",glossary:"juzhicuozhuwang"},"，则民服；举枉错诸直，则民不服。”"]],note:"哀公问：怎样做百姓才服？孔子答：「举直错诸枉，则民服」——把正直者举起来、置于邪枉者之上（错＝置，枉＝邪曲），百姓便服；「举枉错诸直，则民不服」。此章言用人关涉民心。"},{id:"ershi",label:"二十、临之以庄则敬",showLabel:!0,sentences:[["季康子问：“使民敬、忠以劝，如之何？”子曰：“临之以庄，则敬；孝慈，则忠；举善而教不能，则劝。”"]],note:"季康子问：要使百姓恭敬、尽忠而又互相劝勉，怎么办？孔子答：「临之以庄，则敬」——以庄重临下，百姓自敬；「孝慈，则忠」——能孝慈，百姓自忠；「举善而教不能，则劝」——举用善人、教导不能者，百姓自相劝勉。"},{id:"ershiyi",label:"二十一、是亦为政",showLabel:!0,sentences:[["或谓孔子曰：“子奚不为政？”子曰：“《书》云：‘孝乎惟孝，友于兄弟，",{text:"施于有政",glossary:"shiyuyouzheng"},"。’是亦为政，奚其为为政？”"]],note:"有人问孔子：您为什么不去从政？孔子答：《书》云「孝乎惟孝，友于兄弟，施于有政」（孝于亲、友于兄弟，把此德推及政事）。「是亦为政，奚其为为政」——这就是从政，何必一定要做官才算从政？"},{id:"ershier",label:"二十二、人而无信",showLabel:!0,sentences:[["子曰：“人而无信，不知其可也。大车无",{text:"輗",glossary:"ni"},"，小车无",{text:"軏",glossary:"yue-che"},"，其何以行之哉？”"]],note:"「人而无信，不知其可也」——人若没有信，不知他如何行得通。「大车无輗，小车无軏，其何以行之哉」——大车没有輗、小车没有軏（皆辕端与横木相接的关键），怎么走得动？以车喻信，言信为立身之关键。"},{id:"ershisan",label:"二十三、虽百世可知也",showLabel:!0,sentences:[["子张问：“十世可知也？”子曰：“殷",{text:"因",glossary:"yin"},"于夏礼，所损益，可知也；周因于殷礼，所损益，可知也。其或继周者，虽百世，可知也。”"]],note:"子张问：十世（十代）之后可知吗？孔子答：殷承夏礼，所损益可知；周承殷礼，所损益可知；「其或继周者，虽百世，可知也」——将来继周者，虽百世之后亦可推知。此章言礼有因革，故百世可推。"},{id:"ershisi",label:"二十四、见义不为无勇",showLabel:!0,sentences:[["子曰：“非其鬼而祭之，",{text:"谄",glossary:"chan"},"也；见义不为，无勇也。”"]],note:"「非其鬼而祭之，谄也」——不是自己该祭的鬼却去祭，是谄媚；「见义不为，无勇也」——见到该做的却不做，是没有勇气。一章两义，皆言「不当为而为」与「当为而不为」。"}],r=[{id:"de",term:"德",pinyin:"dé",meaning:"得于己者、内在的德性。为政以德，是以自身的德性去感召，而非以政令去驱使。"},{id:"beichen",term:"北辰",pinyin:"běi chén",meaning:"北极星。古人观察天象，以为众星环拱北极，故取以为喻——在上者守其位，在下者自然归向。"},{id:"gong",term:"共",pinyin:"gǒng",meaning:"同「拱」，环绕。众星共之，谓群星环绕北极而运行。"},{id:"bi",term:"蔽",pinyin:"bì",meaning:"概括、涵盖。一言以蔽之，即用一句话总括。"},{id:"siwuxie",term:"思无邪",pinyin:"sī wú xié",meaning:"语出《诗经·鲁颂·駉》。思：一说为语助词（无义），一说指思想。朱熹取「思想纯正」义——《诗》三百篇归于正。"},{id:"daozhiyizheng",term:"道之以政",pinyin:"dǎo zhī yǐ zhèng",meaning:"用政令来引导。道：同「导」。"},{id:"qizhiyixing",term:"齐之以刑",pinyin:"qí zhī yǐ xíng",meaning:"用刑罚来整治。齐：整齐、约束。"},{id:"ge",term:"格",pinyin:"gé",meaning:"归正、向善。一说「至」（达到要求）。有耻且格：既知羞耻，又能自我归正。"},{id:"shiwu",term:"十有五",pinyin:"shí yòu wǔ",meaning:"十五岁。有：同「又」，用于整数与零数之间。"},{id:"zhiyuxue",term:"志于学",pinyin:"zhì yú xué",meaning:"立志于学问。此为孔子自述修学历程的起点。"},{id:"tianming",term:"天命",pinyin:"tiān mìng",meaning:"天所赋予的使命与规律。五十而知天命：到五十岁才明白自己在天地间的位置与所当为。"},{id:"ershun",term:"耳顺",pinyin:"ěr shùn",meaning:"听到各种不同的话，都能通达无碍、不生抵触。一说指「耳闻其言即知其微旨」。"},{id:"yuju",term:"逾矩",pinyin:"yú jǔ",meaning:"超越规矩。从心所欲而不逾矩：自由与法度合一，不必勉强而不越界。"},{id:"ji",term:"疾",pinyin:"jí",meaning:"病。父母唯其疾之忧：一说指父母只为子女的疾病担忧（因疾病非人力可免）；一说指子女只应让父母为自己的病担忧（其余皆当自守）。今从前说。"},{id:"yang",term:"养",pinyin:"yǎng",meaning:"供养、赡养。此处指提供饮食居处等物质照料。"},{id:"jing",term:"敬",pinyin:"jìng",meaning:"恭敬、尊重。孝不止于养活，关键是心里存着敬。"},{id:"senan",term:"色难",pinyin:"sè nán",meaning:"（侍奉父母时）始终保持和悦的容色，最难。色：容色、脸色。"},{id:"zhuan",term:"馔",pinyin:"zhuàn",meaning:"吃喝、陈设食物。此处指让长辈先吃。"},{id:"sou",term:"廋",pinyin:"sōu",meaning:"隐藏、藏匿。人焉廋哉：人怎么藏得住呢？"},{id:"wenguerzhixin",term:"温故而知新",pinyin:"wēn gù ér zhī xīn",meaning:"温习旧的知识而能有新的体会。重在「新得」——不是重复，是从旧材料里读出未读出过的东西。"},{id:"qi",term:"器",pinyin:"qì",meaning:"器皿。器物各有专用，君子不器：君子不应只具备某一种用途，而当通达广博。"},{id:"xianxingqiyan",term:"先行其言",pinyin:"xiān xíng qí yán",meaning:"先把要说的话做出来。而后从之：然后再说。"},{id:"zhouerbuibi",term:"周而不比",pinyin:"zhōu ér bù bǐ",meaning:"周：普遍团结；比：结党营私。君子与人广泛团结而不勾结。"},{id:"wang",term:"罔",pinyin:"wǎng",meaning:"迷惘、无所收获。只学不思，则昏而无得。"},{id:"dai",term:"殆",pinyin:"dài",meaning:"危险、疑惑不定。只思不学，则流于空想而危疑。"},{id:"gonghuyiduan",term:"攻乎异端",pinyin:"gōng hū yì duān",meaning:"攻：专治、专攻（一说攻击）。异端：另一端、不合正道之说。此句歧解甚多，今取「专攻一端而不通其余，则有害」。"},{id:"huiru",term:"诲女",pinyin:"huì rǔ",meaning:"教你。女：同「汝」，你。"},{id:"zhizhi",term:"知",pinyin:"zhì",meaning:"同「智」。是知也：这才是真正的智慧。"},{id:"xueganlu",term:"学干禄",pinyin:"xué gān lù",meaning:"学习求取官职俸禄。干：求取；禄：俸禄。"},{id:"queyi",term:"阙疑",pinyin:"quē yí",meaning:"对有疑问的地方暂时搁置不说。阙：同「缺」，空缺、保留。"},{id:"guayou",term:"寡尤",pinyin:"guǎ yóu",meaning:"少过失。尤：过错。"},{id:"juzhicuozhuwang",term:"举直错诸枉",pinyin:"jǔ zhí cuò zhū wǎng",meaning:"举用正直的人，把他放在邪曲的人之上。错：同「措」，安置。"},{id:"shiyuyouzheng",term:"施于有政",pinyin:"shī yú yǒu zhèng",meaning:"把（孝悌之风）推行到政事上去。施：推行。"},{id:"ni",term:"輗",pinyin:"ní",meaning:"牛车车辕前端与横木衔接的销钉。无輗则车不能行。"},{id:"yue-che",term:"軏",pinyin:"yuè",meaning:"马车车辕前端与横木衔接的销钉。与「輗」相对，皆车上关键的小部件。"},{id:"yin",term:"因",pinyin:"yīn",meaning:"沿袭、继承。殷因于夏礼：殷代沿袭夏代的礼制。"},{id:"chan",term:"谄",pinyin:"chǎn",meaning:"谄媚、巴结。非其鬼而祭之，是巴结不该巴结的对象。"}];return(p,n)=>{const g=t("DaoTextReading"),l=t("DaoKeywordCards");return h(),m("div",null,[n[0]||(n[0]=e("h1",{id:"论语·为政",tabindex:"-1"},[i("论语·为政 "),e("a",{class:"header-anchor",href:"#论语·为政","aria-label":'Permalink to "论语·为政"'},"​")],-1)),n[1]||(n[1]=e("h2",{id:"【原典层】原文",tabindex:"-1"},[i("【原典层】原文 "),e("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),n[2]||(n[2]=e("p",null,[i("《为政》一路下来，讲的是"),e("strong",null,"怎么把一个地方带好，以及一个人怎么把自己立起来"),i("——两件事在孔子这里是一件事：为政以德，靠的是自身的分量，不是权术。")],-1)),n[3]||(n[3]=e("p",null,"这一篇里有几处是《论语》全书最常被引用的：「十五志于学」一节的自述、「温故而知新」、「学而不思则罔」、「知之为知之」。它还留下了孔子论孝的四段回答（孟懿子、孟武伯、子游、子夏问孝），四问四答，各不相同——因人而异，是这一篇最见孔子教法的地方。",-1)),n[4]||(n[4]=e("p",null,"默认竹简沉浸通读；切「经典阅读」可点生词。",-1)),a(g,{colophon:"为政第二 · 二十四章",tone:"ink",sections:s,glossary:r,"default-mode":"slips","aria-label":"论语·为政 原文"}),n[5]||(n[5]=e("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[i("【原典层】注音与字词 "),e("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),a(l,{items:[{term:"德",pinyin:["dé"],meaning:"得于己者、内在的德性。为政以德，是以自身的德性去感召，而非以政令去驱使。"},{term:"北辰",pinyin:["běi","chén"],meaning:"北极星。古人观察天象，以为众星环拱北极，故取以为喻——在上者守其位，在下者自然归向。"},{term:"共",pinyin:["gǒng"],meaning:"同「拱」，环绕。众星共之，谓群星环绕北极而运行。"},{term:"蔽",pinyin:["bì"],meaning:"概括、涵盖。一言以蔽之，即用一句话总括。"},{term:"思无邪",pinyin:["sī","wú","xié"],meaning:"语出《诗经·鲁颂·駉》。思：一说为语助词（无义），一说指思想。朱熹取「思想纯正」义——《诗》三百篇归于正。"},{term:"道之以政",pinyin:["dǎo","zhī","yǐ","zhèng"],meaning:"用政令来引导。道：同「导」。"},{term:"齐之以刑",pinyin:["qí","zhī","yǐ","xíng"],meaning:"用刑罚来整治。齐：整齐、约束。"},{term:"格",pinyin:["gé"],meaning:"归正、向善。一说「至」（达到要求）。有耻且格：既知羞耻，又能自我归正。"},{term:"十有五",pinyin:["shí","yòu","wǔ"],meaning:"十五岁。有：同「又」，用于整数与零数之间。"},{term:"志于学",pinyin:["zhì","yú","xué"],meaning:"立志于学问。此为孔子自述修学历程的起点。"},{term:"天命",pinyin:["tiān","mìng"],meaning:"天所赋予的使命与规律。五十而知天命：到五十岁才明白自己在天地间的位置与所当为。"},{term:"耳顺",pinyin:["ěr","shùn"],meaning:"听到各种不同的话，都能通达无碍、不生抵触。一说指「耳闻其言即知其微旨」。"},{term:"逾矩",pinyin:["yú","jǔ"],meaning:"超越规矩。从心所欲而不逾矩：自由与法度合一，不必勉强而不越界。"},{term:"疾",pinyin:["jí"],meaning:"病。父母唯其疾之忧：一说指父母只为子女的疾病担忧（因疾病非人力可免）；一说指子女只应让父母为自己的病担忧（其余皆当自守）。今从前说。"},{term:"养",pinyin:["yǎng"],meaning:"供养、赡养。此处指提供饮食居处等物质照料。"},{term:"敬",pinyin:["jìng"],meaning:"恭敬、尊重。孝不止于养活，关键是心里存着敬。"},{term:"色难",pinyin:["sè","nán"],meaning:"（侍奉父母时）始终保持和悦的容色，最难。色：容色、脸色。"},{term:"馔",pinyin:["zhuàn"],meaning:"吃喝、陈设食物。此处指让长辈先吃。"},{term:"廋",pinyin:["sōu"],meaning:"隐藏、藏匿。人焉廋哉：人怎么藏得住呢？"},{term:"温故而知新",pinyin:["wēn","gù","ér","zhī","xīn"],meaning:"温习旧的知识而能有新的体会。重在「新得」——不是重复，是从旧材料里读出未读出过的东西。"},{term:"器",pinyin:["qì"],meaning:"器皿。器物各有专用，君子不器：君子不应只具备某一种用途，而当通达广博。"},{term:"先行其言",pinyin:["xiān","xíng","qí","yán"],meaning:"先把要说的话做出来。而后从之：然后再说。"},{term:"周而不比",pinyin:["zhōu","ér","bù","bǐ"],meaning:"周：普遍团结；比：结党营私。君子与人广泛团结而不勾结。"},{term:"罔",pinyin:["wǎng"],meaning:"迷惘、无所收获。只学不思，则昏而无得。"},{term:"殆",pinyin:["dài"],meaning:"危险、疑惑不定。只思不学，则流于空想而危疑。"},{term:"攻乎异端",pinyin:["gōng","hū","yì","duān"],meaning:"攻：专治、专攻（一说攻击）。异端：另一端、不合正道之说。此句歧解甚多，今取「专攻一端而不通其余，则有害」。"},{term:"诲女",pinyin:["huì","rǔ"],meaning:"教你。女：同「汝」，你。"},{term:"知",pinyin:["zhì"],meaning:"同「智」。是知也：这才是真正的智慧。"},{term:"学干禄",pinyin:["xué","gān","lù"],meaning:"学习求取官职俸禄。干：求取；禄：俸禄。"},{term:"阙疑",pinyin:["quē","yí"],meaning:"对有疑问的地方暂时搁置不说。阙：同「缺」，空缺、保留。"},{term:"寡尤",pinyin:["guǎ","yóu"],meaning:"少过失。尤：过错。"},{term:"举直错诸枉",pinyin:["jǔ","zhí","cuò","zhū","wǎng"],meaning:"举用正直的人，把他放在邪曲的人之上。错：同「措」，安置。"},{term:"施于有政",pinyin:["shī","yú","yǒu","zhèng"],meaning:"把（孝悌之风）推行到政事上去。施：推行。"},{term:"輗",pinyin:["ní"],meaning:"牛车车辕前端与横木衔接的销钉。无輗则车不能行。"},{term:"軏",pinyin:["yuè"],meaning:"马车车辕前端与横木衔接的销钉。与「輗」相对，皆车上关键的小部件。"},{term:"因",pinyin:["yīn"],meaning:"沿袭、继承。殷因于夏礼：殷代沿袭夏代的礼制。"},{term:"谄",pinyin:["chǎn"],meaning:"谄媚、巴结。非其鬼而祭之，是巴结不该巴结的对象。"}]}),n[6]||(n[6]=u('<p>全篇生词的完整释义在<a href="/Dao/reference/glossary/">字词释义字典</a>中统一维护。</p><h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一篇在说什么" tabindex="-1">象：这一篇在说什么 <a class="header-anchor" href="#象-这一篇在说什么" aria-label="Permalink to &quot;象：这一篇在说什么&quot;">​</a></h3><p>《为政》二十四章，一半在说<strong>怎么带人</strong>，一半在说<strong>怎么成己</strong>。开头一句「为政以德，譬如北辰」定下基调——<strong>治理不是靠推，是靠立</strong>：上位者把自己站住了，下面的人自然环绕过来。这一篇的最后一句「见义不为，无勇也」，则是另一面的补充：光有德不够，该出手时还得出手。</p><p>中间大段，是孔子论修养与治学。「十五志于学」这一节，是他对自己一生的自述，也是全篇最完整的成长时间表；「温故而知新」「学而不思则罔」「知之为知之」，则都是方法与态度。还有四段问答孝，问的是同一个人同一个字，答的却因人而异——这本身就是一种教法。</p><h3 id="理-为什么值得读" tabindex="-1">理：为什么值得读 <a class="header-anchor" href="#理-为什么值得读" aria-label="Permalink to &quot;理：为什么值得读&quot;">​</a></h3><ul><li><strong>它把「管理」的着力点转向了自己</strong>：「为政以德」不是道德口号，是一个判断——<strong>靠外在约束只能让人「免而无耻」，靠内在分量才能让人「有耻且格」</strong>。「道之以政，齐之以刑……道之以德，齐之以礼」两句对举，把两种治理方式的深浅说得极清楚。</li><li><strong>它给出一条完整的成长时间线</strong>：「十五志于学」这一节，从十五到七十，每隔十年一个阶段。它让人看到：<strong>修养不是一个结果，是一段有台阶的路</strong>——而孔子自己到了七十才「从心所欲不逾矩」。</li><li><strong>它把「孝」从形式拉回到态度</strong>：四段问孝里，「不敬，何以别乎」与「色难」两句最扎人——<strong>养而不敬，与养狗马无异；孝不在于替父母做了什么，而在于脸上有没有好颜色</strong>。</li><li><strong>它讲清了「知」的诚实</strong>：「知之为知之，不知为不知，是知也」——这是一句几乎每个中国孩子都背过的话，但真正做到的人不多。<strong>承认不知道，才是知的开始。</strong></li><li><strong>它把「学」和「思」摆成一对</strong>：「学而不思则罔，思而不学则殆」，两句话把今天说的「输入」与「内化」讲完了。</li></ul><h3 id="用-今日可用之处" tabindex="-1">用：今日可用之处 <a class="header-anchor" href="#用-今日可用之处" aria-label="Permalink to &quot;用：今日可用之处&quot;">​</a></h3><ol><li><strong>想带好一个团队，先看自己站得稳不稳</strong>：「为政以德，譬如北辰」——你在开会、定规则、批评人之前，先问一句：<strong>我自己做到了吗？</strong> 别人是听你的话，还是看你的样？</li><li><strong>用十年一个刻度复盘自己</strong>：拿「十五志于学」对一遍——十五立志了吗？三十立住了吗？四十还在迷惑什么？<strong>不必与孔子对齐，但值得有刻度。</strong></li><li><strong>对父母，检查自己的「色」</strong>：钱给了、事办了，但说话时耐不耐得住性子？「色难」两个字，是这一篇最日常的考题。</li><li><strong>承认「不知道」</strong>：在职场上，「我不知道，我去确认」比硬答一个错的答案要值钱得多。这就是「不知为不知，是知也」。</li><li><strong>学到东西要过一遍脑子</strong>：读完一本书问一句「它跟我已知的哪件事对上了」，这就是「温故而知新」。</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>《为政》这一篇，讲的是一个很朴素的问题：<strong>怎么把事做好，同时怎么把人做好。</strong></p><p>孔子的答案分两层。往外的这一层，他说别靠权力顶——你自己站住了，别人自会围过来；让人羞耻，比让人害怕更管用。往内的这一层，他说修养有台阶，十五、三十、四十、五十、六十、七十，一步一个台阶，急不得；他还说，读书要思考、思考要读书，知道就说知道、不知道就说不知道。</p><p>有意思的是，这一篇的收尾：「非其鬼而祭之，谄也；见义不为，无勇也。」——<strong>既反对讨好不该讨好的人，也反对该出手时不出手。</strong> 一个说别谄，一个说别怂，两面一括，是极完整的人格要求。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p>待补——这一节留给自己的读后想法。</p></blockquote><p>可以按这几条慢慢写：</p><ul><li>「为政以德，譬如北辰」——我有没有过「自己站住了，事情自然顺了」的经历？反过来，有没有「拼命推、却推不动」的经历？</li><li>四段问孝（孟懿子、孟武伯、子游、子夏），孔子答得都不一样。为什么同一件事要因人而答？我要问的，是其中的哪一个问题？</li><li>「知之为知之，不知为不知」——上一次我为了面子而不知道装知道，是什么时候？</li><li>「君子不器」——我做事的范围，是在变宽，还是在变窄（越做越专、越专越窄）？</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/lizhimingde/sishu-wujing/lunyu/">论语总览</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/">四书五经总览</a></li><li>同栏目：<a href="/Dao/lizhimingde/sishu-wujing/daxue/">大学</a> · <a href="/Dao/lizhimingde/sishu-wujing/zhongyong/">中庸</a> · <a href="/Dao/lizhimingde/sishu-wujing/mengzi/">孟子</a></li><li>上篇：<a href="/Dao/lizhimingde/sishu-wujing/lunyu/chapter-01">论语·学而</a>　下篇：<a href="/Dao/lizhimingde/sishu-wujing/lunyu/chapter-03">论语·八佾</a></li><li>参考：《论语》朱熹《四书章句集注·论语集注》；杨伯峻《论语译注》</li></ul>',19))])}}});export{x as __pageData,c as default};
